actions.script:
def ctcAnnual = emp.ctcAnnual as BigDecimal def ctcMonthly = ctcAnnual / 12 def basicPct = (ss.basicPercentOfGross ?: 40) as BigDecimal
// --- Step 1: Derive Gross from CTC by subtracting employer contributions --- def estBasic = ctcMonthly * basicPct / 100 def pfEligible = emp.pfApplicable == 'Y' ? Math.min(estBasic as double, 15000.0) as BigDecimal : 0 def empPfCost = pfEligible * 0.12 // employer PF 12% def empPfAdmin = pfEligible * 0.005 // admin 0.5% def empEdli = pfEligible * 0.005 // EDLI 0.5% def empGratuity = ss.includeGratuityInCtc == 'Y' ? estBasic * 15 / 26 / 12 : 0
def totalEmployerEst = empPfCost + empPfAdmin + empEdli + empGratuity def grossMonthly = ctcMonthly - totalEmployerEst
// Recalculate with actual gross-based basic def basic = grossMonthly * basicPct / 100 pfEligible = emp.pfApplicable == 'Y' ? Math.min(basic as double, 15000.0) as BigDecimal : 0 empPfCost = pfEligible * 0.12 empPfAdmin = pfEligible * 0.005 empEdli = pfEligible * 0.005 empGratuity = ss.includeGratuityInCtc == 'Y' ? basic * 15 / 26 / 12 : 0
// ESI check: applicable if monthly gross <= 21000 def esiEmployerRate = 0.0325 as BigDecimal def esiEmployeeRate = 0.0075 as BigDecimal def esiEmployerAmt = 0 as BigDecimal if (emp.esiApplicable == 'Y' && grossMonthly <= 21000) { if (ss.includeEsiInCtc == 'Y') { esiEmployerAmt = grossMonthly * esiEmployerRate } } totalEmployerEst = empPfCost + empPfAdmin + empEdli + empGratuity + esiEmployerAmt grossMonthly = ctcMonthly - totalEmployerEst
// --- Step 2: Break down gross into components --- basic = grossMonthly * basicPct / 100 def hraPct = emp.isMetroCity == 'Y' ? 50 : ((ss.hraPercentOfBasic ?: 40) as BigDecimal) def hraAmt = basic * hraPct / 100 def daAmt = basic * ((ss.daPercentOfBasic ?: 0) as BigDecimal) / 100 def convAmt = (ss.conveyanceMonthly ?: 0) as BigDecimal def medAmt = (ss.medicalMonthly ?: 0) as BigDecimal def ltaAmt = basic * ((ss.ltaPercentOfBasic ?: 0) as BigDecimal) / 100 def specAmt = grossMonthly - basic - hraAmt - daAmt - convAmt - medAmt - ltaAmt if (specAmt < 0) specAmt = 0
// --- Step 3: LWP adjustment --- def lwp = (lwpDays ?: 0) as BigDecimal def wDays = (workingDays ?: 26) as BigDecimal def pDays = wDays - lwp def proRate = wDays > 0 ? pDays / wDays : 1 def lwpDeduction = grossMonthly - (grossMonthly * proRate)
basic = (basic * proRate).setScale(0, java.math.RoundingMode.HALF_UP) hraAmt = (hraAmt * proRate).setScale(0, java.math.RoundingMode.HALF_UP) daAmt = (daAmt * proRate).setScale(0, java.math.RoundingMode.HALF_UP) convAmt = (convAmt * proRate).setScale(0, java.math.RoundingMode.HALF_UP) medAmt = (medAmt * proRate).setScale(0, java.math.RoundingMode.HALF_UP) specAmt = (specAmt * proRate).setScale(0, java.math.RoundingMode.HALF_UP) ltaAmt = (ltaAmt * proRate).setScale(0, java.math.RoundingMode.HALF_UP) def actualGross = basic + hraAmt + daAmt + convAmt + medAmt + specAmt + ltaAmt
// --- Step 4: Employee deductions --- def pfBase = basic + daAmt def pfCeiling = Math.min(pfBase as double, 15000.0) as BigDecimal def epfEmp = emp.pfApplicable == 'Y' ? (pfCeiling * 0.12).setScale(0, java.math.RoundingMode.HALF_UP) : 0 def esiEmp = (emp.esiApplicable == 'Y' && grossMonthly <= 21000) ? (actualGross * esiEmployeeRate).setScale(0, java.math.RoundingMode.HALF_UP) : 0
// Salary advance recovery def advRecovery = 0 as BigDecimal
// Store values for PT and TDS calculation (done after script via service calls) context.calcBasic = basic context.calcHra = hraAmt context.calcDa = daAmt context.calcConveyance = convAmt context.calcMedical = medAmt context.calcSpecial = specAmt context.calcLta = ltaAmt context.calcGross = actualGross context.calcEpfEmp = epfEmp context.calcEsiEmp = esiEmp context.calcGrossMonthlyFull = grossMonthly context.calcPaidDays = pDays context.calcLwpDeduction = lwpDeduction.setScale(0, java.math.RoundingMode.HALF_UP)
// --- Step 5: Employer contributions --- def epfEmpr = emp.pfApplicable == 'Y' ? (pfCeiling * 0.0367).setScale(0, java.math.RoundingMode.HALF_UP) : 0 def epsEmpr = emp.pfApplicable == 'Y' ? (pfCeiling * 0.0833).setScale(0, java.math.RoundingMode.HALF_UP) : 0 def adminCh = emp.pfApplicable == 'Y' ? (pfCeiling * 0.005).setScale(0, java.math.RoundingMode.HALF_UP) : 0 def edliCh = emp.pfApplicable == 'Y' ? (pfCeiling * 0.005).setScale(0, java.math.RoundingMode.HALF_UP) : 0 def esiEmpr = (emp.esiApplicable == 'Y' && grossMonthly <= 21000) ? (actualGross * esiEmployerRate).setScale(0, java.math.RoundingMode.HALF_UP) : 0 def gratProv = (basic * 15 / 26 / 12).setScale(0, java.math.RoundingMode.HALF_UP)
context.calcEpfEmpr = epfEmpr context.calcEpsEmpr = epsEmpr context.calcAdminCh = adminCh context.calcEdliCh = edliCh context.calcEsiEmpr = esiEmpr context.calcGratProv = gratProv context.calcAdvRecovery = advRecovery

def calObj = java.util.Calendar.getInstance()
calObj.set(periodYear as int, (periodMonth as int) - 1, 1)
context.totalDaysInMonth = calObj.getActualMaximum(java.util.Calendar.DAY_OF_MONTH)

def gross = monthlyGross as BigDecimal
def annualGross = gross * 12

// Standard deduction
def stdDeduction = regime == 'New' ? 75000 : 50000
def taxableIncome = annualGross - stdDeduction

// Old regime: subtract declared deductions
if (regime == 'Old' && declaration) {
    def sec80c = Math.min((declaration.section80c ?: 0) as double, 150000.0) as BigDecimal
    // Employee EPF is part of 80C
    sec80c = Math.min(sec80c + (annualEpfEmployee ?: 0), 150000) as BigDecimal
    taxableIncome -= sec80c
    taxableIncome -= Math.min((declaration.section80d ?: 0) as double, 100000.0) as BigDecimal
    taxableIncome -= (declaration.section80e ?: 0) as BigDecimal
    taxableIncome -= (declaration.section80g ?: 0) as BigDecimal
    taxableIncome -= Math.min((declaration.section80tta ?: 0) as double, 10000.0) as BigDecimal
    taxableIncome -= (declaration.hraExemptionClaimed ?: 0) as BigDecimal
    taxableIncome -= (declaration.ltaExemptionClaimed ?: 0) as BigDecimal
    taxableIncome -= Math.min((declaration.homeLoanInterest ?: 0) as double, 200000.0) as BigDecimal
    taxableIncome -= Math.min((declaration.npsContribution ?: 0) as double, 50000.0) as BigDecimal
    taxableIncome -= (declaration.otherExemptions ?: 0) as BigDecimal
} else if (regime == 'New') {
    // New regime: no deductions except standard deduction (already applied)
    // NPS employer contribution up to 14% of salary is exempt but that's complex
}

if (taxableIncome < 0) taxableIncome = 0

// Calculate tax using slab rates
def annualTax = 0 as BigDecimal
for (slab in slabs) {
    def slabFrom = (slab.fromAmount ?: 0) as BigDecimal
    def slabTo = (slab.toAmount ?: 999999999) as BigDecimal
    def rate = (slab.taxRatePercent ?: 0) as BigDecimal

    if (taxableIncome > slabFrom && rate > 0) {
        def taxableInSlab = Math.min(taxableIncome as double, slabTo as double) as BigDecimal
        taxableInSlab = taxableInSlab - slabFrom + 1
        annualTax += taxableInSlab * rate / 100
    }
}

// Apply rebate u/s 87A
if (regime == 'New' && taxableIncome <= 1200000) {
    def rebate = Math.min(annualTax as double, 60000.0) as BigDecimal
    annualTax -= rebate
} else if (regime == 'Old' && taxableIncome <= 500000) {
    annualTax = 0
}

// Health & Education Cess 4%
if (annualTax > 0) {
    annualTax = (annualTax * 1.04).setScale(0, java.math.RoundingMode.HALF_UP)
}

context.annualTaxProjected = annualTax
context.monthlyTds = annualTax > 0 ?
    (annualTax / 12).setScale(0, java.math.RoundingMode.HALF_UP) : 0
